const assert = require('node:assert/strict');
const path = require('node:path');
const { withAttachmentApp } = require('./attachment-route-parity.js');

const START = Date.parse('2026-11-05T00:00:00.000Z');

// Two isolated production web owners, not a relabelled copy of one stream.
// Only the runtime records and registry seed are inputs; HTTP, events and
// deltas are generated by the real Node authority. No external AI process.
async function observeNodeEpochs(timers) {
  const { WebEventBus } = require('../../packages/controlled-instance/src/web/events.ts');
  const original = WebEventBus.prototype.publish;
  const output = { ai: {}, app: {} };
  const identities = new Set();
  const sessionIdentities = new Set();
  timers.enable({ apis: ['Date'], now: START });
  try {
    for (const [epoch, offset] of [['old', 0], ['next', 10000]]) {
      const base = START + offset;
      timers.setTime(base);
      let runtime, sessionId, records = [], startupResolve;
      const published = [];
      const startup = new Promise(resolve => { startupResolve = resolve; });
      WebEventBus.prototype.publish = function(type, payload, ...args) {
        const result = original.call(this, type, payload, ...args);
        if (/^(ai|app)-session\.(snapshot|patch)$/.test(type)) {
          // WebSocket uses JSON.stringify: undefined object properties are
          // absent on wire. Keep nulls/arrays/values exactly as serialized.
          published.push(JSON.parse(JSON.stringify({ type, payload })));
          if (type === 'ai-session.snapshot' && payload.meta.revision === 1) startupResolve();
        }
        return result;
      };
      await withAttachmentApp(async app => {
        await app.ready();
        let deadline;
        try {
          await Promise.race([startup, new Promise((_, reject) => {
            deadline = setTimeout(() => reject(new Error('missing production startup event')), 3000);
          })]);
        } finally { clearTimeout(deadline); }
        const request = async (url, payload) => {
          const response = await app.inject({ method: payload === undefined ? 'GET' : 'PUT', url, payload });
          assert.equal(response.statusCode, 200, response.body);
          return response.json().data;
        };
        const states = { ai: [], app: [] };
        for (let revision = 1; revision <= 3; revision++) {
          timers.setTime(base + (revision - 1) * 1000);
          records = [{ id: 'app_epoch', appId: 'terminal-tty', title: `${epoch}-${revision}`, kind: 'tty',
            status: 'running', createdAt: new Date(base).toISOString(), updatedAt: new Date(base).toISOString(),
            workspace: { cwd: '/workspace' }, paths: { sessionDir: '/tmp/session', logDir: '/tmp/logs' } }];
          runtime.emit(revision === 1 ? 'created' : 'updated', records[0]);
          if (revision > 1) await request(`/api/ai-sessions/${sessionId}/story`, { storyId: `${epoch}-${revision}` });
          states.ai.push(await request('/api/ai-sessions/state'));
          states.app.push(await request('/api/apps/sessions/state'));
        }
        for (const topic of ['ai', 'app']) {
          const streamId = states[topic][0].streamId;
          assert.ok(!identities.has(streamId), 'each owner/topic has a distinct epoch');
          identities.add(streamId);
          const prefix = topic === 'ai' ? '/api/ai-sessions' : '/api/apps/sessions';
          const delta = await request(`${prefix}?streamId=${encodeURIComponent(streamId)}&sinceRevision=1`);
          const events = published.filter(event => event.type.startsWith(`${topic}-session.`));
          assert.equal(events.length, 3);
          const traces = new Map();
          function normalize(value, key = '') {
            if (key === 'streamId') { assert.equal(value, streamId); return `${topic}-${epoch}`; }
            if (key === 'id' && value === sessionId) return `<ai-${epoch}-session>`;
            if (Array.isArray(value)) return value.map(item => normalize(item));
            if (value && typeof value === 'object') {
              const result = {};
              for (const [name, item] of Object.entries(value)) {
                if (name === 'traceId') {
                  assert.match(item, new RegExp(`^${topic === 'ai' ? 'ais' : 'aps'}_evt_`));
                  if (traces.has(value.revision)) assert.equal(item, traces.get(value.revision));
                  else { assert.ok(![...traces.values()].includes(item)); traces.set(value.revision, item); }
                  result[name] = `<${topic}-${epoch}-trace-${value.revision}>`;
                } else result[name] = normalize(item, name);
              }
              return result;
            }
            return value;
          }
          output[topic][epoch] = normalize({ states: states[topic], events, delta });
        }
      }, root => {
        const { AppRuntimeManager } = require('../../packages/app-runtime/src/runtime.ts');
        const { resolveStoragePaths } = require('../../packages/core/src/storage/paths.ts');
        const { createAiSessionRegistry } = require('../../packages/ai-session-runtime/src/ai-session-registry.ts');
        runtime = new AppRuntimeManager(resolveStoragePaths());
        runtime.listSessions = () => records;
        const registry = createAiSessionRegistry({ dir: path.join(root, 'ai-sessions') });
        sessionId = registry.start({ agent: 'codex', creationSource: 'ai-session', providerSessionId: 'provider-epoch',
          title: 'Epoch session', status: 'idle', phase: 'unknown' }, { timestamp: new Date(base).toISOString() }).id;
        assert.ok(!sessionIdentities.has(sessionId));
        sessionIdentities.add(sessionId);
        return { appRuntime: runtime, aiSessionRegistry: registry };
      });
    }
    assert.equal(identities.size, 4);
    assert.equal(sessionIdentities.size, 2);
    return output;
  } finally { WebEventBus.prototype.publish = original; timers.reset(); }
}

module.exports = { observeNodeEpochs };
